SELECT 
FROM ai_business_flow_callback_inbox
WHERE tenant_id = #{tenantId}
  AND event_id = #{eventId}
LIMIT 1

SELECT 
FROM ai_business_flow_callback_inbox
WHERE tenant_id = #{tenantId}
  AND id = #{id}
LIMIT 1

SELECT MAX(event_sequence)
FROM ai_business_flow_callback_inbox
WHERE tenant_id = #{tenantId}
  AND aggregate_key = #{aggregateKey}
  AND consume_status = 'COMPLETED'

mapper.update:
UPDATE ai_business_flow_callback_inbox
SET consume_status = 'DEAD',
    next_retry_time = NULL,
    lock_owner = NULL,
    lock_time = NULL,
    error_type = 'LeaseExpiredAfterRetryLimit',
    update_time = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND consume_status = 'PROCESSING'
  AND retry_count >= #{maxRetryCount}
  AND (lock_time IS NULL OR lock_time <= #{staleBefore})

UPDATE ai_business_flow_callback_inbox
SET consume_status = 'COMPLETED',
    next_retry_time = NULL,
    lock_owner = NULL,
    lock_time = NULL,
    error_type = NULL,
    completed_time = #{now},
    update_time = #{now}
WHERE tenant_id = #{inbox.tenantId}
  AND id = #{inbox.id}
  AND consume_status = 'PROCESSING'
  AND lock_owner = #{inbox.lockOwner}

UPDATE ai_business_flow_callback_inbox
SET consume_status = #{status},
    next_retry_time = #{nextRetryTime},
    lock_owner = NULL,
    lock_time = NULL,
    error_type = #{errorType},
    update_time = #{now}
WHERE tenant_id = #{inbox.tenantId}
  AND id = #{inbox.id}
  AND consume_status = 'PROCESSING'
  AND lock_owner = #{inbox.lockOwner}
